#include <stdfloat>
#include <vector>
#include <print>

int main() {
    // Simulate storing ML weights in bfloat16 vs float32
    std::vector<std::bfloat16_t> bf16_weights = {
        static_cast<std::bfloat16_t>(0.5f),
        static_cast<std::bfloat16_t>(-0.25f),
        static_cast<std::bfloat16_t>(1.0f),
        static_cast<std::bfloat16_t>(0.125f)
    };

    std::vector<std::float32_t> f32_weights = {0.5f, -0.25f, 1.0f, 0.125f};

    std::println("bfloat16 storage: {} bytes for 4 weights",
        bf16_weights.size() * sizeof(std::bfloat16_t));
    std::println("float32 storage:  {} bytes for 4 weights",
        f32_weights.size() * sizeof(std::float32_t));

    // Arithmetic works — convert to float32 for computation
    float sum = 0.0f;
    for (auto w : bf16_weights)
        sum += static_cast<float>(w);
    std::println("sum of bf16 weights: {}", sum);

    // Type system: float16_t and float32_t are distinct types
    auto f16 = static_cast<std::float16_t>(1.5f);
    std::float32_t f32 = 1.5f;
    std::println("float16_t == float32_t value: {}", static_cast<float>(f16) == f32);
}

#include <bit>
#include <cstdint>
#include <print>

int main() {
    // Network byte order conversion (big-endian)
    uint32_t host_value = 0x12345678;
    uint32_t network_value = std::byteswap(host_value);

    std::println("host:    {:#010x}", host_value);
    std::println("network: {:#010x}", network_value);
    std::println("round-trip: {:#010x}", std::byteswap(network_value));

    // constexpr: evaluated at compile time
    constexpr uint16_t port = std::byteswap(uint16_t{8080});
    std::println("port 8080 in network order: {:#06x}", port);

    // PNG magic number: big-endian in file -> little-endian on x86
    constexpr uint32_t png_magic_be = 0x89504E47u;
    constexpr uint32_t png_magic_le = std::byteswap(png_magic_be);
    std::println("PNG magic LE: {:#010x}", png_magic_le);
}

#include <bit>
#include <cstdint>
#include <print>

int main() {
    uint8_t  u8  = 0xABu;
    uint16_t u16 = 0xABCDu;
    uint32_t u32 = 0xABCDEF12u;
    uint64_t u64 = 0xABCDEF1234567890ULL;

    std::println("byteswap(0xAB):               {:#04x}",  std::byteswap(u8));
    std::println("byteswap(0xABCD):             {:#06x}",  std::byteswap(u16));
    std::println("byteswap(0xABCDEF12):         {:#010x}", std::byteswap(u32));
    std::println("byteswap(0xABCDEF1234567890): {:#018x}", std::byteswap(u64));

    // Signed types work too
    int32_t si = 0x00000001;
    std::println("byteswap(int32 1): {:#010x}", static_cast<uint32_t>(std::byteswap(si)));
}

#include <vector>
#include <algorithm>
#include <ranges>
#include <print>

int main() {
    // shift_left: shift elements left by 2
    std::vector<int> data = {1, 2, 3, 4, 5};
    auto valid = std::ranges::shift_left(data, 2);
    std::print("after shift_left(2), valid: ");
    for (int x : valid) std::print("{} ", x);
    std::println("");
    std::println("vector size still: {}", data.size());

    // shift_right: shift elements right by 1
    std::vector<int> data2 = {1, 2, 3, 4, 5};
    auto valid2 = std::ranges::shift_right(data2, 1);
    std::print("after shift_right(1), valid: ");
    for (int x : valid2) std::print("{} ", x);
    std::println("");

    // Practical: sliding-window buffer — discard 2 old, write 2 new
    std::vector<int> buf = {10, 20, 30, 40, 50};
    std::ranges::shift_left(buf, 2);
    buf[3] = 60;
    buf[4] = 70;
    std::print("sliding window: ");
    for (int x : buf) std::print("{} ", x);
    std::println("");
}

#include <memory>
#include <print>

// Simulate a C API that allocates a resource via an out-parameter
struct Resource {
    int value;
    explicit Resource(int v) : value(v) {}
};

int c_api_create(Resource** out, int val) {
    *out = new Resource(val);
    return 0; // success
}

void c_api_destroy(Resource* r) {
    delete r;
}

int main() {
    // Old pattern (before out_ptr):
    {
        Resource* raw = nullptr;
        c_api_create(&raw, 42);
        std::unique_ptr<Resource, decltype(&c_api_destroy)> ptr{raw, c_api_destroy};
        std::println("old pattern value: {}", ptr->value);
    }

    // New pattern with std::out_ptr:
    {
        std::unique_ptr<Resource, decltype(&c_api_destroy)> ptr{nullptr, c_api_destroy};
        c_api_create(std::out_ptr(ptr), 99);
        std::println("out_ptr pattern value: {}", ptr->value);
    }

    std::println("both resources properly destroyed");
}
